reset role;
select extensions.ok((select count(*)=1 from public.organization_access_codes where organization_id='f4200000-0000-4000-8000-000000000001' and active),'Only one active code row remains');
select extensions.ok((select count(*)=1 from public.organization_members where user_id='f4100000-0000-4000-8000-000000000007' and status='active'),'Exactly one approved membership');
select extensions.ok(not exists(select 1 from public.audit_logs a join issued i on a.metadata_redacted::text like '%'||i.code||'%'),'No code secrets in audit after whole workflow');
select extensions.ok((select prosecdef and proconfig @> array['search_path=""'] from pg_proc where oid='public.organization_access_code_state(uuid)'::regprocedure),'RPC has fixed empty search path and definer');
select extensions.ok((select prosecdef and proconfig @> array['search_path=""'] from pg_proc where oid='public.manage_organization_access_code(uuid,uuid,text)'::regprocedure),'RPC has fixed empty search path and definer');
select extensions.ok((select prosecdef and proconfig @> array['search_path=""'] from pg_proc where oid='public.own_organization_code_entry()'::regprocedure),'RPC has fixed empty search path and definer');
select extensions.ok((select prosecdef and proconfig @> array['search_path=""'] from pg_proc where oid='public.submit_organization_access_code(text)'::regprocedure),'RPC has fixed empty search path and definer');
select * from extensions.finish(); rollback;
